'use strict';
const $=s=>document.querySelector(s), canvas=$('#scene'),ctx=canvas.getContext('2d');
const WEAPONS=[{id:'rifle',name:'Kestrel AR-8',type:'ASSAULT RIFLE',damage:36,range:5,ap:3,weight:14,price:0,desc:'Reliable burst fire. Balanced range and accuracy.'},{id:'shotgun',name:'Breacher SG-4',type:'SCATTER CANNON',damage:60,range:3,ap:3,weight:18,price:1500,desc:'Devastating close-range impact. Close the distance.'},{id:'missile',name:'Vesper MRL',type:'MISSILE POD',damage:45,range:7,ap:4,weight:22,price:2400,desc:'Long-range guided ordnance. Ignores cover penalties.'},{id:'rail',name:'Longbow R-12',type:'RAIL CANNON',damage:70,range:8,ap:5,weight:26,price:3600,desc:'Precision anti-armor fire. Powerful, but demanding.'}];
const FRAMES=[{name:'WARDEN',model:'WDN–07',role:'ASSAULT',color:'#899681',hp:160,arm:92,leg:110,move:4,armor:5},{name:'KESTREL',model:'KST–12',role:'RECON',color:'#b6a37c',hp:126,arm:78,leg:100,move:5,armor:2},{name:'BASILISK',model:'BSK–04',role:'SUPPORT',color:'#708c92',hp:180,arm:100,leg:90,move:3,armor:7}];
const PILOTS=[{name:'Mara Voss',call:'ROOK',skill:'Overdrive',desc:'+2 AP this turn. Once per battle.',color:'#9cae8b'},{name:'Jin Takeda',call:'GHOST',skill:'Deadeye',desc:'Next attack deals 50% more damage. Once per battle.',color:'#c1a477'},{name:'Elena Ortiz',call:'ANCHOR',skill:'Field repair',desc:'Restore 45 body HP. Once per battle.',color:'#83a4ac'}];
const CONTRACTS=[{name:'Ashes of the relay',place:'KARST BASIN · SECTOR 07',tag:'RECOVERY OPERATION',pay:3200,difficulty:1,desc:'A rival lance occupies a decommissioned relay station. Clear the site and recover its navigation core.',enemies:3,color:'#707e60'},{name:'The iron corridor',place:'VANTA INDUSTRIAL · SECTOR 12',tag:'INTERDICTION',pay:4600,difficulty:2,desc:'Intercept an armored patrol before it reaches the refinery. Expect reinforced enemy chassis.',enemies:4,color:'#a07856'},{name:'No quiet frontier',place:'HALCYON OUTSKIRTS · SECTOR 19',tag:'HIGH-RISK CONTRACT',pay:6800,difficulty:3,desc:'A veteran company has claimed the frontier. Break their command lance and make your name.',enemies:5,color:'#658b92'}];
function fresh(){return{version:1,day:1,credits:4500,rep:0,wins:0,kills:0,owned:['rifle'],units:FRAMES.map((f,i)=>({weapon:i===2?'missile':'rifle',level:1,xp:0,condition:100,upgrade:0})),history:[]}}
let save;try{save=JSON.parse(localStorage.getItem('iron-vow-career'));if(!validSave(save))save=fresh()}catch{save=fresh()}
let page='hangar',selected=0,battle=null,action='move',targetPart='body',effects=[],hover=null,clock=0,last=0,muted=true,audio=null,toastTimer;
function persist(){try{localStorage.setItem('iron-vow-career',JSON.stringify(save))}catch{toast('Storage unavailable. Keep this tab open to retain your career.')}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function money(n){return n.toLocaleString()+' CR'}
function weapon(id){return WEAPONS.find(w=>w.id===id)||WEAPONS[0]}
function sound(type){if(muted)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();let o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.type=type==='shot'?'sawtooth':'sine';o.frequency.setValueAtTime(type==='shot'?110:type==='boom'?65:420,audio.currentTime);o.frequency.exponentialRampToValueAtTime(25,audio.currentTime+.22);g.gain.setValueAtTime(type==='shot'?.12:.08,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.3);o.start();o.stop(audio.currentTime+.3)}catch{}}
$('#sound').onclick=()=>{muted=!muted;$('#sound').textContent=muted?'SOUND OFF':'SOUND ON';$('#sound').setAttribute('aria-label',muted?'Enable sound':'Mute sound');sound('click')};
function nav(){ $('#nav').innerHTML=['hangar','contracts','workshop','pilots','career'].map(p=>`<button data-page="${p}" class="${p===page?'active':''}" ${battle?'disabled':''}>${p.toUpperCase()}</button>`).join('');$('#credits').textContent=money(save.credits);$('#day').textContent='DAY '+String(save.day).padStart(3,'0');}
function stat(name,val,ratio){return `<div class="stat"><span>${name}</span><b>${val}</b></div>${ratio!==undefined?`<div class="bar"><i style="width:${ratio}%"></i></div>`:''}`}
function render(){nav();let f=FRAMES[selected],u=save.units[selected],p=PILOTS[selected],w=weapon(u.weapon);if(battle){renderBattle();return}
if(page==='hangar')$('#ui').innerHTML=`<div class="hangar-title"><div class="eyebrow">INDEPENDENT MERCENARY COMPANY</div><h1>STEEL BONES.<br><span>IRON VOW.</span></h1><p>Every machine has a purpose.<br>Every pilot has a price.<br>Build your lance. Write your legacy.</p></div><div class="bay-label">HANGAR 04 / CHASSIS INSPECTION</div><div class="mech-label"><span>◈ REACTOR ONLINE</span><span>${f.model} / ${f.role}</span></div><aside class="sidepanel"><div class="paneltop"><span class="eyebrow">UNIT 0${selected+1}</span><span class="tag">${u.condition===100?'COMBAT READY':'REPAIR ADVISED'}</span></div><h2>${f.name}</h2><div class="stat"><span>${f.model} · ${f.role}</span><b>LV ${u.level}</b></div><div class="rule"></div><div class="part-stats">${stat('BODY INTEGRITY',f.hp+u.upgrade*25,100)}${stat('ARMOR RATING',f.armor+u.upgrade*2)}${stat('MOBILITY',f.move+' TILES')}${stat('PRIMARY',w.type)}</div><div class="pilot"><div class="portrait">${p.call[0]}</div><div>${p.name}<small>${p.call} / ${p.skill.toUpperCase()}</small></div></div>${stat('CONDITION',u.condition+'%',u.condition)}<button class="primary full" data-page="contracts">FIND A CONTRACT ↗</button><div class="note">3 PILOTS · ${save.wins} CONTRACTS COMPLETED<br>PROGRESS SAVES AUTOMATICALLY</div></aside><div class="lance">${FRAMES.map((m,i)=>`<button class="mechcard ${i===selected?'active':''}" data-select="${i}"><span class="eyebrow">${m.role}</span><span class="num">0${i+1} ↗</span><h3>${m.name}</h3><small>${PILOTS[i].call} · ${weapon(save.units[i].weapon).type}</small></button>`).join('')}</div><div class="footnote">IRON VOW / TACTICAL MECH OPERATIONS &nbsp;&nbsp; • &nbsp;&nbsp; ROTATING CHASSIS PREVIEW</div>`;
if(page==='contracts')$('#ui').innerHTML=`<div class="page"><div class="pagehead"><div><div class="eyebrow">OPERATIONS / CONTRACT BOARD</div><h1>THE NEXT PAYDAY.</h1></div><p>Deploy your three-unit lance.<br>Complete objectives. Claim salvage.</p></div><div class="grid">${CONTRACTS.map((c,i)=>`<article class="card"><div class="contract-map" style="background:linear-gradient(35deg,#182822,${c.color})">0${i+1} / ${['◈','⌁','△'][i]}</div><div class="eyebrow">${c.place}</div><h2>${c.name}</h2><span class="tag">${c.tag}</span><p style="margin-top:20px">${c.desc}</p><div class="rule"></div>${stat('THREAT LEVEL','◆'.repeat(c.difficulty)+'◇'.repeat(3-c.difficulty))}${stat('HOSTILES',c.enemies+' UNITS')}${stat('GUARANTEED PAY',money(c.pay))}<button class="primary full" data-deploy="${i}">ACCEPT & DEPLOY ↗</button><div class="note">${i===0?'RECOMMENDED FOR YOUR FIRST SORTIE':'REPAIR & UPGRADE BEFORE DEPLOYING'}</div></article>`).join('')}</div><p class="note">Combat: select a unit → click a blue tile to move → choose FIRE → click an enemy. End your turn when ready.</p></div>`;
if(page==='workshop')$('#ui').innerHTML=`<div class="page"><div class="pagehead"><div><div class="eyebrow">ENGINEERING / MECH LAB</div><h1>BUILT TO ENDURE.</h1></div><p>Equip weapons. Reinforce armor.<br>Prepare every machine for deployment.</p></div><div style="display:flex;gap:10px;margin-bottom:25px">${FRAMES.map((f,i)=>`<button data-select="${i}" class="${i===selected?'active':''}">${f.name}</button>`).join('')}</div><div class="split"><article class="card"><span class="eyebrow">${f.model} / ${p.call}</span><h2>${f.name}</h2>${stat('BODY',f.hp+u.upgrade*25+' HP')}${stat('ARMOR',f.armor+u.upgrade*2)}${stat('CHASSIS REINFORCEMENT','MK '+(u.upgrade+1))}${stat('CONDITION',u.condition+'%',u.condition)}<p class="note">Reinforcement adds 25 body HP and 2 armor. Repairs restore combat integrity. Free field patches recover damaged units to 35%, so your company can always take another contract.</p><button data-patch="${selected}" ${u.condition>=35?'disabled':''}>FIELD PATCH · FREE</button> <button data-repair="${selected}" ${u.condition===100?'disabled':''}>REPAIR · ${money(repairCost(selected))}</button> <button data-upgrade="${selected}" ${u.upgrade>=3?'disabled':''}>${u.upgrade>=3?'MAX REINFORCEMENT':'REINFORCE · '+money(1800+u.upgrade*1200)}</button></article><article class="card"><div class="eyebrow">WEAPON HARDPOINT / SELECT LOADOUT</div><div class="equipment">${WEAPONS.map(a=>{let own=save.owned.includes(a.id)||u.weapon===a.id;return `<button data-equip="${a.id}" class="${u.weapon===a.id?'active':''}"><small>${a.type}</small><h3>${a.name}</h3><small>${a.damage} DMG / ${a.range} RNG / ${a.ap} AP</small><p style="font-size:10px;margin-top:8px">${a.desc}</p><div class="note">${u.weapon===a.id?'● EQUIPPED':own?'EQUIP →':money(a.price)+' · BUY & EQUIP'}</div></button>`}).join('')}</div></article></div></div>`;
if(page==='pilots')$('#ui').innerHTML=`<div class="page"><div class="pagehead"><div><div class="eyebrow">PERSONNEL / ACTIVE LANCE</div><h1>HUMAN AT THE CORE.</h1></div><p>Experience sharpens your pilots.<br>Each level adds 5% weapon damage.</p></div><div class="grid">${PILOTS.map((p,i)=>{let u=save.units[i];return `<article class="card"><div class="portrait" style="width:80px;height:95px;font-size:58px">${p.call[0]}</div><div class="eyebrow" style="margin-top:24px">CALLSIGN / ${p.call}</div><h2>${p.name}</h2><span class="tag">ASSIGNED: ${FRAMES[i].name}</span><div class="rule"></div>${stat('PILOT LEVEL',u.level)}${stat('EXPERIENCE',u.xp+' / '+(u.level*100),100*u.xp/(u.level*100))}<h3 style="margin:22px 0 10px">${p.skill}</h3><p>${p.desc}</p><div class="rule"></div><p>${['Former border guard. Holds the line when contracts turn ugly. The first to drop and the last to leave.','A reconnaissance specialist with a quiet reputation. Makes every shot count, especially the impossible ones.','Field engineer turned combat pilot. Keeps the company moving, one repaired reactor at a time.'][i]}</p></article>`}).join('')}</div></div>`;
if(page==='career')$('#ui').innerHTML=`<div class="page"><div class="pagehead"><div><div class="eyebrow">COMPANY RECORD / PERSISTENT CAREER</div><h1>LEAVE A MARK.</h1></div><span class="rank">${save.rep>=100?'VETERAN COMPANY':save.rep>=30?'RECOGNIZED LANCE':'INDEPENDENT OUTFIT'}</span></div><div class="grid"><div class="card"><span class="eyebrow">COMPANY RESERVES</span><h2>${money(save.credits)}</h2><p>Available for repairs, weapons and chassis reinforcement.</p></div><div class="card"><span class="eyebrow">SUCCESSFUL CONTRACTS</span><h2>${String(save.wins).padStart(2,'0')}</h2><p>${save.kills} enemy machines neutralized. ${save.rep} reputation earned.</p></div><div class="card"><span class="eyebrow">DEPLOYMENT DAY</span><h2>${String(save.day).padStart(3,'0')}</h2><p>Your career is stored in this browser. Export a backup to carry it with you.</p></div></div><div class="card" style="margin-top:24px"><span class="eyebrow">AFTER-ACTION RECORD</span>${save.history.length?save.history.slice().reverse().map(h=>`<div class="stat"><span>DAY ${String(h.day).padStart(3,'0')} / ${h.name}</span><b>${h.win?'COMPLETED +'+money(h.pay):'WITHDRAWN'}</b></div>`).join(''):'<p style="margin-top:20px">No sorties recorded. Your first contract is waiting.</p>'}<div class="settings"><button id="export">EXPORT CAREER</button><button id="import">IMPORT BACKUP</button><input hidden type="file" id="file" accept="application/json"><button id="reset">NEW CAREER</button><button id="guide">FIELD MANUAL</button></div></div></div>`;
bind();}
function repairCost(i){return Math.ceil((100-save.units[i].condition)*14)}
function bind(){document.querySelectorAll('[data-patch]').forEach(b=>b.onclick=()=>{save.units[selected].condition=Math.max(35,save.units[selected].condition);persist();render();toast('Emergency field patch applied. Full repairs recommended.')});document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{if(!battle){page=b.dataset.page;render();sound('click')}});document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{selected=+b.dataset.select;render();sound('click')});document.querySelectorAll('[data-deploy]').forEach(b=>b.onclick=()=>deploy(+b.dataset.deploy));document.querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>{let w=weapon(b.dataset.equip),u=save.units[selected];if(!save.owned.includes(w.id)&&u.weapon!==w.id){if(save.credits<w.price)return toast('Insufficient credits');save.credits-=w.price;save.owned.push(w.id)}u.weapon=w.id;persist();render();toast(w.name+' equipped')});document.querySelectorAll('[data-repair]').forEach(b=>b.onclick=()=>{let cost=repairCost(selected);if(save.credits<cost)return toast('Insufficient credits');save.credits-=cost;save.units[selected].condition=100;persist();render();toast('Chassis restored to full integrity')});document.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>{let u=save.units[selected],cost=1800+u.upgrade*1200;if(save.credits<cost)return toast('Insufficient credits');save.credits-=cost;u.upgrade++;persist();render();toast('Chassis reinforcement installed')});if($('#export')){$('#export').onclick=()=>{let blob=new Blob([JSON.stringify(save,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='iron-vow-career.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{try{let n=JSON.parse(await e.target.files[0].text());if(!validSave(n))throw Error();save=n;persist();render();toast('Career backup restored')}catch{toast('Invalid career backup')}};$('#reset').onclick=()=>modal('NEW CAREER?','This replaces your company progress in this browser. Export a backup first if you want to keep it.',[{text:'KEEP MY CAREER',fn:closeModal},{text:'START FRESH',fn:()=>{save=fresh();persist();closeModal();render()}}]);$('#guide').onclick=guide}}
function validSave(s){return s&&s.version===1&&Number.isFinite(s.credits)&&s.credits>=0&&Number.isInteger(s.day)&&s.day>0&&Number.isFinite(s.rep)&&Number.isFinite(s.wins)&&Number.isFinite(s.kills)&&Array.isArray(s.owned)&&s.owned.every(x=>WEAPONS.some(w=>w.id===x))&&Array.isArray(s.history)&&s.history.length<=500&&s.history.every(h=>typeof h.name==='string'&&CONTRACTS.some(c=>c.name===h.name)&&Number.isFinite(h.day)&&typeof h.win==='boolean'&&Number.isFinite(h.pay))&&Array.isArray(s.units)&&s.units.length===3&&s.units.every(u=>WEAPONS.some(w=>w.id===u.weapon)&&Number.isInteger(u.level)&&u.level>0&&u.level<100&&Number.isFinite(u.xp)&&u.xp>=0&&Number.isFinite(u.condition)&&u.condition>=0&&u.condition<=100&&Number.isInteger(u.upgrade)&&u.upgrade>=0&&u.upgrade<=3)}
function modal(title,body,buttons){$('#modal').hidden=false;$('#modal').innerHTML=`<div class="modalbox" role="dialog" aria-modal="true" aria-label="${title}"><div class="eyebrow">IRON VOW / COMMAND UPLINK</div><h1>${title}</h1><div>${body}</div><div class="buttons">${buttons.map((b,i)=>`<button class="${i===buttons.length-1?'primary':''}" id="modal-${i}">${b.text}</button>`).join('')}</div></div>`;buttons.forEach((b,i)=>$('#modal-'+i).onclick=b.fn);$('#modal button').focus()}
function closeModal(){$('#modal').hidden=true}
function guide(){modal('FIELD MANUAL',`<p>Your objective is to neutralize every enemy. All three pilots act during your turn. Select a unit from the bottom bar or click its mech.</p><p><b>MOVE:</b> Click a blue tile. Movement costs one AP per tile, following a path around cover. Each pilot starts with 8 AP.</p><p><b>FIRE:</b> Select a target part on the right, then click an enemy in the red range overlay. A firing preview shows damage and accuracy. Body destruction disables a mech. Destroying its weapon arm stops attacks; destroyed legs stop movement. Losing the shield arm halves armor.</p><p><b>SKILL:</b> Each pilot can activate their unique skill once per battle. <b>BRACE:</b> Spend 2 AP to halve incoming damage until your next turn.</p><p>Cover reduces hit chance for rifles, shotguns and railguns. Missiles ignore cover. End your turn when you have used your AP. Enemies then move and attack. Withdraw if you need to preserve your machines.</p><p>Complete contracts to earn credits, experience, reputation and salvage. Repair damaged chassis in the workshop before your next sortie. Progress saves in this browser.</p>`,[{text:'UNDERSTOOD',fn:closeModal}])}
// Tactical simulation: part HP, reachable tiles, AP, cover, level scaling and persistent rewards.
function makeUnit(i,team,x,z){let f=FRAMES[i%3],u=team==='ally'?save.units[i]:{upgrade:Math.max(0,battle.contract.difficulty-1),condition:100,level:battle.contract.difficulty,weapon:i%3===2?'missile':i%3===1?'shotgun':'rifle'};let k=team==='ally'?Math.max(.3,u.condition/100):1;let max={body:f.hp+u.upgrade*25,left:f.arm,right:f.arm,legs:f.leg};return{id:team+i,index:i,team,x,z,vx:x,vz:z,frame:i%3,name:team==='ally'?f.name:['JACKAL','RAVEN','MARAUDER'][i%3]+' '+(i+1),weapon:u.weapon,level:u.level,armor:f.armor+u.upgrade*2,max,hp:Object.fromEntries(Object.entries(max).map(([a,b])=>[a,Math.round(b*k)])),ap:8,brace:false,skill:false,boost:false,alive:true}}
function deploy(i){if(save.units.some(u=>u.condition<30)){modal('REPAIR REQUIRED','<p>One or more chassis have less than 30% integrity. Repair them in the workshop before deploying.</p>',[{text:'OPEN WORKSHOP',fn:()=>{closeModal();page='workshop';selected=save.units.findIndex(u=>u.condition<30);render()}}]);return}battle={contract:CONTRACTS[i],turn:1,phase:'player',units:[],cover:new Set(['2,3','3,3','7,3','7,4','5,6','6,6','2,7','8,7','4,1']),log:['Lance deployed. Reactor signatures detected.'],busy:false};battle.units=[makeUnit(0,'ally',1,8),makeUnit(1,'ally',2,9),makeUnit(2,'ally',0,9),...Array.from({length:CONTRACTS[i].enemies},(_,j)=>makeUnit(j,'enemy',j%3*3+2,Math.floor(j/3)))];selected=0;action='move';targetPart='body';effects=[];hover=null;render();sound('click');if(save.history.length===0)guide()}
function current(){return battle?.units.find(u=>u.team==='ally'&&u.index===selected&&u.alive)}
function occupied(x,z){return battle.units.some(u=>u.alive&&u.x===x&&u.z===z)}
function paths(u){let max=Math.min(u.ap,u.hp.legs>0?FRAMES[u.frame].move:0),m=new Map([[u.x+','+u.z,0]]),queue=[[u.x,u.z]];for(let k=0;k<queue.length;k++){let [x,z]=queue[k],d=m.get(x+','+z);if(d>=max)continue;for(let [dx,dz]of[[1,0],[-1,0],[0,1],[0,-1]]){let a=x+dx,b=z+dz,key=a+','+b;if(a<0||b<0||a>9||b>9||m.has(key)||battle.cover.has(key)||occupied(a,b))continue;m.set(key,d+1);queue.push([a,b])}}return m}
function distance(a,b){return Math.abs(a.x-b.x)+Math.abs(a.z-b.z)}
function inCover(t){return [[1,0],[-1,0],[0,1],[0,-1]].some(([x,z])=>battle.cover.has((t.x+x)+','+(t.z+z)))}
function hitChance(a,t,part){return Math.min(.98,Math.max(.5,.96-(part==='body'?0:.13)-(inCover(t)&&a.weapon!=='missile'?.19:0)+.015*(a.level-1)))}
function damage(a,t){return Math.max(5,Math.round((weapon(a.weapon).damage*(1+.05*(a.level-1))*(a.boost?1.5:1)-(t.hp.left===0?Math.floor(t.armor/2):t.armor))*(t.brace?.5:1)))}
function addLog(s){battle.log.push(s);battle.log=battle.log.slice(-4)}
function renderBattle(){nav();let u=current(),enemy=hover&&battle.units.find(t=>t.alive&&t.team==='enemy'&&t.x===hover.x&&t.z===hover.z),target=enemy||battle.units.find(t=>t.alive&&t.team==='enemy');$('#ui').innerHTML=`<div class="battle-top"><span class="eyebrow">${battle.contract.tag}</span><h2>${battle.contract.name}</h2><p>Eliminate the hostile lance.<br>${battle.units.filter(t=>t.team==='enemy'&&t.alive).length} hostile signatures remaining</p><div style="display:flex;gap:6px;margin-top:12px"><button class="icon" id="manual">MANUAL</button><button class="icon" id="withdraw">WITHDRAW</button></div></div><div class="turn">ROUND ${String(battle.turn).padStart(2,'0')}<small>${battle.phase==='player'?'YOUR LANCE / TAKE COMMAND':'HOSTILE LANCE / STAND BY'}</small></div><aside class="combatpanel"><span class="eyebrow">TARGET SUBSYSTEM</span><h3>${target?.name||'AREA SECURED'}</h3><div class="parts">${['body','right','left','legs'].map(p=>`<button data-part="${p}" class="${p===targetPart?'active':''}"><span>${({body:'BODY',right:'WEAPON ARM',left:'SHIELD ARM',legs:'LEGS'})[p]}</span><b>${target?target.hp[p]+'/'+target.max[p]:'—'}</b></button>`).join('')}</div><div class="note">${enemy&&u?`${Math.round(hitChance(u,enemy,targetPart)*100)}% HIT · ${damage(u,enemy)} DMG<br>${distance(u,enemy)<=weapon(u.weapon).range?'IN WEAPON RANGE':'OUT OF RANGE'}${inCover(enemy)?' · COVER':''}`:'HOVER / TAP ENEMY TO INSPECT'}<br>BODY DESTRUCTION = UNIT DISABLED</div></aside><div class="log">${battle.log.map(l=>'› '+l).join('<br>')}</div><div class="hint">${battle.busy?'RESOLVING COMBAT…':action==='move'?'MOVE / CLICK A BLUE TILE · 1 AP PER TILE':'FIRE / CLICK A HOSTILE · '+(u?weapon(u.weapon).ap:3)+' AP PER ATTACK'}</div><div class="battle-bottom"><div class="unitbuttons">${battle.units.filter(t=>t.team==='ally').map(t=>`<button data-unit="${t.index}" class="${t.index===selected?'active':''}" ${!t.alive?'disabled':''}><b>${t.name}</b><small>${t.alive?t.ap+' AP · '+t.hp.body+' HP':'DISABLED'}</small></button>`).join('')}</div><div class="actionbuttons"><button id="move" class="${action==='move'?'active':''}" ${!u||battle.busy?'disabled':''}>MOVE [M]</button><button id="fire" class="${action==='fire'?'active':''}" ${!u||battle.busy?'disabled':''}>FIRE [F]</button><button id="skill" ${!u||u.skill||battle.busy?'disabled':''}>SKILL [Q]</button><button id="brace" ${!u||u.ap<2||u.brace||battle.busy?'disabled':''}>BRACE · 2 AP</button><button id="end" class="primary" ${battle.busy?'disabled':''}>END TURN ↗</button></div></div>`;
document.querySelectorAll('[data-unit]').forEach(b=>b.onclick=()=>{if(!battle.busy){selected=+b.dataset.unit;renderBattle()}});document.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>{targetPart=b.dataset.part;renderBattle()});$('#move').onclick=()=>{action='move';renderBattle()};$('#fire').onclick=()=>{action='fire';renderBattle()};$('#skill').onclick=skill;$('#brace').onclick=()=>{if(u&&u.ap>=2&&!u.brace&&!battle.busy){u.ap-=2;u.brace=true;addLog(u.name+' braced for incoming fire.');renderBattle()}};$('#end').onclick=endTurn;$('#manual').onclick=guide;$('#withdraw').onclick=()=>{if(battle.busy)return;modal('BREAK CONTACT?','<p>Withdraw your lance. You retain earned experience, but forfeit the contract payment and salvage. Combat damage persists.</p>',[{text:'STAY & FIGHT',fn:closeModal},{text:'WITHDRAW',fn:()=>{closeModal();finish(false)}}])}}
function skill(){let u=current();if(!u||u.skill||battle.busy)return;u.skill=true;if(u.index===0)u.ap+=2;if(u.index===1)u.boost=true;if(u.index===2){u.hp.body=Math.min(u.max.body,u.hp.body+45);effects.push({type:'heal',x:u.x,z:u.z,t:1,text:'+45 REPAIR'})}addLog(PILOTS[u.index].call+' activated '+PILOTS[u.index].skill+'.');sound('click');renderBattle()}
const delay=ms=>new Promise(r=>setTimeout(r,ms));
async function moveUnit(u,x,z,cost){u.ap-=cost;u.x=x;u.z=z;sound('click');await delay(280)}
async function shoot(a,t,part){let w=weapon(a.weapon);a.ap-=w.ap;effects.push({type:'shot',x:a.x,z:a.z,tx:t.x,tz:t.z,t:1,color:a.weapon==='rail'?'#b5f8ff':a.weapon==='missile'?'#ffbd71':'#e7f58c'});sound('shot');await delay(260);if(Math.random()>hitChance(a,t,part)){effects.push({type:'text',x:t.x,z:t.z,t:1,text:'MISS'});addLog(a.name+' missed '+t.name+'.')}else{let d=damage(a,t);t.hp[part]=Math.max(0,t.hp[part]-d);effects.push({type:'boom',x:t.x,z:t.z,t:1,big:false});effects.push({type:'text',x:t.x,z:t.z,t:1,text:'−'+d+' '+part.toUpperCase()});addLog(a.name+' → '+t.name+' / '+part+' −'+d);sound('boom');if(t.hp.body<=0){t.alive=false;effects.push({type:'boom',x:t.x,z:t.z,t:1,big:true});addLog(t.name+' neutralized.');if(a.team==='ally'){save.kills++;save.units[a.index].xp+=35}}else if(t.hp[part]===0)addLog(t.name+': '+part+' destroyed.');}a.boost=false;await delay(420)}
function checkEnd(){if(!battle.units.some(u=>u.alive&&u.team==='enemy')){finish(true);return true}if(!battle.units.some(u=>u.alive&&u.team==='ally')){finish(false);return true}return false}
async function endTurn(){if(!battle||battle.busy)return;battle.busy=true;battle.phase='enemy';battle.units.filter(u=>u.team==='enemy'&&u.alive).forEach(u=>{u.ap=8;u.brace=false});renderBattle();for(let e of battle.units.filter(u=>u.team==='enemy'&&u.alive)){let allies=battle.units.filter(u=>u.team==='ally'&&u.alive);if(!allies.length)break;let t=allies.sort((a,b)=>distance(e,a)-distance(e,b))[0],w=weapon(e.weapon);if(distance(e,t)>w.range&&e.hp.legs>0){let possible=[...paths(e)].filter(([key,cost])=>cost<=8-w.ap).map(([key,cost])=>{let [x,z]=key.split(',').map(Number);return{x,z,cost,d:Math.abs(t.x-x)+Math.abs(t.z-z)}}).sort((a,b)=>a.d-b.d);if(possible[0]&&possible[0].d<distance(e,t))await moveUnit(e,possible[0].x,possible[0].z,possible[0].cost)}while(e.ap>=w.ap&&e.hp.right>0&&distance(e,t)<=w.range&&t.alive){await shoot(e,t,'body');renderBattle();if(checkEnd())return}if(e.hp.right===0)addLog(e.name+' cannot fire: weapon arm destroyed.');await delay(200)}if(checkEnd())return;battle.turn++;battle.phase='player';battle.busy=false;battle.units.filter(u=>u.team==='ally'&&u.alive).forEach(u=>{u.ap=8;u.brace=false});if(!current())selected=battle.units.find(u=>u.alive&&u.team==='ally').index;addLog('Round '+battle.turn+'. Your lance has the initiative.');renderBattle()}
function finish(win){let b=battle,c=b.contract;let salvage=win?450+c.difficulty*200:0,pay=win?c.pay+salvage:0;save.credits+=pay;save.rep+=win?c.difficulty*10:0;if(win)save.wins++;b.units.filter(u=>u.team==='ally').forEach(u=>{let s=save.units[u.index];s.condition=Math.max(12,Math.round(100*(u.hp.body+u.hp.right+u.hp.left+u.hp.legs)/(u.max.body+u.max.right+u.max.left+u.max.legs)));s.xp+=win?70:20;while(s.xp>=s.level*100){s.xp-=s.level*100;s.level++}});save.history.push({name:c.name,day:save.day,win,pay});save.history=save.history.slice(-100);save.day++;persist();battle=null;page='career';render();modal(win?'CONTRACT FULFILLED.':'LANCE EXTRACTED.',`<p>${win?'The field is yours. Your pilots return with hard-earned experience and recovered enemy components.':'Your pilots have been recovered. The machines need work. There will be another contract.'}</p>${stat('CONTRACT PAYMENT',money(win?c.pay:0))}${stat('SALVAGE SOLD',money(salvage))}${stat('REPUTATION',win?'+'+c.difficulty*10:'UNCHANGED')}<p class="note">Damage persists. Visit the workshop to restore your lance.</p>`,[{text:'COMPANY RECORD',fn:closeModal},{text:'REPAIR & REFIT',fn:()=>{closeModal();page='workshop';render()}}])}
// Isometric renderer. Every chassis is assembled from separate modeled armor plates.
let W=innerWidth,H=innerHeight,DPR=Math.min(devicePixelRatio||1,2),scale=50,origin={x:0,y:0},faces=[],lines=[];
function resize(){W=innerWidth;H=innerHeight;DPR=Math.min(devicePixelRatio||1,2);canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0)}window.addEventListener('resize',resize);resize();
function project(x,y,z){return{x:origin.x+(x-z)*scale*.866,y:origin.y+(x+z)*scale*.42-y*scale}}
function polygon(points,fill,stroke){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=.7;ctx.stroke()}}
function shade(c,k){let n=parseInt(c.slice(1),16);return '#'+[n>>16,(n>>8)&255,n&255].map(x=>Math.max(0,Math.min(255,Math.round(x*k))).toString(16).padStart(2,'0')).join('')}
function box(x,y,z,w,h,d,color,yaw=0,cx=0,cz=0){let pts=[];for(let yy of[-1,1])for(let zz of[-1,1])for(let xx of[-1,1]){let a=x+xx*w/2,b=z+zz*d/2;pts.push({x:cx+a*Math.cos(yaw)-b*Math.sin(yaw),y:y+yy*h/2,z:cz+a*Math.sin(yaw)+b*Math.cos(yaw)})}const fs=[[0,1,3,2,.5],[4,6,7,5,1.35],[0,4,5,1,.65],[2,3,7,6,.95],[0,2,6,4,.6],[1,5,7,3,1.05]];for(let ids of fs){let p=ids.slice(0,4).map(i=>pts[i]);faces.push({p,color:shade(color,ids[4]),depth:p.reduce((s,q)=>s+q.x+q.z+q.y*.8,0)/4,edge:color==='#b6e5cb'||color==='#e5f58a'?null:'#07121077'})}}
function flush(){faces.sort((a,b)=>a.depth-b.depth);for(let f of faces)polygon(f.p.map(p=>project(p.x,p.y,p.z)),f.color,f.edge);faces=[]}
function mech(x,z,frame,team,time,yaw=0,unit=null,hero=false){let f=FRAMES[frame],c=team==='enemy'?'#a36e5f':f.color,dark='#293431',metal='#59625b',accent=team==='enemy'?'#ff9a6b':'#e5f58a',alive=!unit||unit.alive,bob=hero?Math.sin(time*1.3)*.015:0;let B=(a,y,b,w,h,d,col)=>box(a,y+bob,b,w,h,d,col,yaw,x,z);if(!alive){B(0,.22,0,1.15,.35,1.1,'#323a34');B(.45,.18,.3,.55,.3,.7,'#4c493c');return}let stride=unit?Math.min(1,Math.abs(unit.x-unit.vx)+Math.abs(unit.z-unit.vz))*Math.sin(time*18)*.13:0;for(let side of[-1,1]){let a=side*.38;B(a,.16,.1, .55,.28,.87,dark);B(a,.29,-.05,.49,.16,.64,c);B(a,.65+stride*side,0,.32,.66,.38,metal);B(a,.74+stride*side,-.2,.45,.46,.24,unit?.hp.legs===0?'#55463a':c);B(a,1.13,0,.43,.25,.4,dark);B(a,1.43,0,.42,.52,.5,c);B(a,1.45,-.28,.3,.27,.07,shade(c,1.25));B(a,1.1,-.26,.22,.15,.08,accent)}B(0,1.72,0,.87,.34,.57,dark);B(0,2.08,0,1.14,.58,.72,c);B(0,2.15,-.4,.7,.32,.16,shade(c,1.18));B(0,2.01,-.48,.35,.09,.04,accent);B(0,2.35,.05,.72,.15,.62,c);B(0,2.68,-.02,.44,.44,.42,c);B(0,2.7,-.245,.38,.1,.04,'#151f1d');B(0,2.7,-.273,.29,.045,.025,accent);B(.18,2.98,.02,.025,.3,.025,metal);for(let side of[-1,1]){let arm=side===1?'right':'left',col=unit&&unit.hp[arm]<=0?'#493d34':c;B(side*.83,2.18,0,.58,.5,.68,col);B(side*.88,1.83,0,.28,.4,.3,metal);B(side*.91,1.57,-.05,.45,.5,.5,col);B(side*.91,1.55,-.32,.28,.28,.08,dark);B(side*.88,2.45,0,.4,.07,.54,shade(col,1.25));if(side===-1){B(side*1.05,1.75,-.2,.17,.8,.62,col);B(side*1.15,1.76,-.23,.04,.4,.4,accent)}}B(0,2.1,.55,.7,.65,.35,dark);for(let s of[-1,1]){B(s*.22,2.3,.72,.18,.33,.18,metal);B(s*.22,2.48,.72,.12,.04,.12,dark)}let wid=unit?.weapon||save.units[frame].weapon;if(wid==='missile'){B(.85,2.72,.12,.62,.38,.66,dark);for(let a of[.7,.95])for(let y of[2.65,2.8])B(a,y,-.23,.1,.1,.045,accent)}else{B(.94,1.49,-.6,.28,.28,.9,dark);B(.94,1.53,-1.03,wid==='rail'?.13:.18,.15,wid==='rail'?1:.35,metal);B(.94,1.54,wid==='rail'?-1.55:-1.25,.13,.08,.06,'#151b18');B(1.1,1.52,-.5,.08,.11,.34,c)}if(hero){B(-.25,2.15,-.5,.075,.26,.02,accent);B(-.36,2.15,-.5,.075,.26,.02,accent)}}
function background(){let g=ctx.createLinearGradient(0,0,W,H);g.addColorStop(0,'#182220');g.addColorStop(.6,'#25302a');g.addColorStop(1,'#0a1716');ctx.fillStyle=g;ctx.fillRect(0,0,W,H)}
function hangar(t){let mobile=W<760;scale=mobile?Math.min(W*.18,H*.11):Math.min(W*.066,H*.115);origin={x:mobile?W*.5:W*.52,y:mobile?H*.66:H*.79};let glow=ctx.createRadialGradient(origin.x,H*.4,0,origin.x,H*.5,W*.48);glow.addColorStop(0,'#94ad6d26');glow.addColorStop(1,'#07131100');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H);for(let i=-9;i<=9;i++){let a=project(i,0,-9),b=project(i,0,9),c=project(-9,0,i),d=project(9,0,i);ctx.strokeStyle='#93b49615';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.moveTo(c.x,c.y);ctx.lineTo(d.x,d.y);ctx.stroke()}for(let i=0;i<6;i++){let x=W*.29+i*W*.115;ctx.fillStyle='#07111070';ctx.fillRect(x,92,9,H*.55);ctx.fillStyle='#a6c68b33';ctx.fillRect(x+9,92,2,H*.5);ctx.fillStyle='#e7f5cd88';ctx.fillRect(x-13,130,34,3)}let plat=[];for(let i=0;i<48;i++){let a=i*Math.PI/24;plat.push(project(Math.cos(a)*2.5,-.08,Math.sin(a)*2.5))}polygon(plat,'#29342d','#71816c55');ctx.save();ctx.shadowColor='#d3e995';ctx.shadowBlur=13;for(let i=0;i<8;i++){let a=i*Math.PI/4;let p1=project(Math.cos(a)*2.35,0,Math.sin(a)*2.35),p2=project(Math.cos(a+.16)*2.35,0,Math.sin(a+.16)*2.35);ctx.strokeStyle='#d3e995';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(p1.x,p1.y);ctx.lineTo(p2.x,p2.y);ctx.stroke()}ctx.restore();let yaw=.35+Math.sin(t*.18)*.35;mech(0,0,selected,'ally',t,yaw,null,true);flush();let g=ctx.createLinearGradient(0,0,W,0);g.addColorStop(0,'#0c1617e8');g.addColorStop(.28,'#0c161711');g.addColorStop(.6,'#0c161700');g.addColorStop(1,'#0c161780');ctx.fillStyle=g;ctx.fillRect(0,92,W,H);ctx.fillStyle='#b9c79d44';for(let i=0;i<28;i++){let x=(i*173.7+t*3)%W,y=110+(i*61.3+t*(i%3+1)*2)%(H-110);ctx.fillRect(x,y,1,1)}}
function tile(x,z,color,stroke,y=0){polygon([[x-.5,y,z-.5],[x+.5,y,z-.5],[x+.5,y,z+.5],[x-.5,y,z+.5]].map(p=>project(...p)),color,stroke)}
function battlefield(t){let mobile=W<760;scale=mobile?Math.min(W/18,H/15):Math.min((W-280)/18,(H-220)/10.7);scale=Math.max(17,scale);origin={x:W*.5,y:mobile?H*.36:H*.32};let u=current(),reachable=u&&battle.phase==='player'&&!battle.busy&&action==='move'?paths(u):null;for(let sum=0;sum<=18;sum++)for(let x=0;x<10;x++){let z=sum-x;if(z<0||z>9)continue;let key=x+','+z,base=(x+z)%2?'#28382f':'#2c3c32';tile(x,z,base,'#76957426');if(reachable?.has(key)&&reachable.get(key)>0)tile(x,z,'#7fd7c227','#7fd7c26a',.008);if(u&&action==='fire'&&distance(u,{x,z})<=weapon(u.weapon).range)tile(x,z,'#e4947020','#e4947044',.008);if(hover?.x===x&&hover?.z===z)tile(x,z,'#e7f58a45','#e7f58a',.016)}for(let key of battle.cover){let [x,z]=key.split(',').map(Number);box(x,.42,z,.85,.84,.85,'#4e5c4b');box(x,.87,z,.93,.08,.93,'#77826b');box(x,.48,z+.44,.6,.15,.02,'#b0ac65')}for(let unit of battle.units){unit.vx+=(unit.x-unit.vx)*.2;unit.vz+=(unit.z-unit.vz)*.2;if(unit.team==='ally'&&unit.alive)tile(unit.x,unit.z,selected===unit.index?'#e5f58a44':'#6dcebd22',selected===unit.index?'#e5f58a':'#6dcebd',.02);mech(unit.vx,unit.vz,unit.frame,unit.team,t,unit.team==='ally'?Math.PI:0,unit)}flush();for(let unit of battle.units.filter(u=>u.alive)){let p=project(unit.vx,3.4,unit.vz);ctx.fillStyle='#0c1815df';ctx.fillRect(p.x-22,p.y-7,44,5);ctx.fillStyle=unit.team==='ally'?'#d7ed8b':'#ee9c7a';ctx.fillRect(p.x-22,p.y-7,44*unit.hp.body/unit.max.body,3);ctx.font='8px monospace';ctx.textAlign='center';ctx.fillStyle=unit.team==='ally'?'#d3e6bb':'#e6b3a0';ctx.fillText(unit.team==='ally'?PILOTS[unit.index].call:unit.name,p.x,p.y-12)}for(let e of effects){if(e.type==='shot'){let a=project(e.x,1.9,e.z),b=project(e.tx,1.8,e.tz);ctx.save();ctx.strokeStyle=e.color;ctx.lineWidth=3;ctx.shadowColor=e.color;ctx.shadowBlur=15;ctx.globalAlpha=e.t;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.restore()}else if(e.type==='boom'){let p=project(e.x,1.2,e.z);ctx.save();ctx.globalAlpha=e.t;let g=ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,scale*(e.big?2:1)*(1-e.t+.2));g.addColorStop(0,'#ffffdd');g.addColorStop(.3,'#ffcb6b');g.addColorStop(.7,'#d2763433');g.addColorStop(1,'#e3991100');ctx.fillStyle=g;ctx.beginPath();ctx.arc(p.x,p.y,scale*(e.big?2:1)*(1-e.t+.2),0,Math.PI*2);ctx.fill();ctx.restore()}else{let p=project(e.x,3.7+(1-e.t),e.z);ctx.globalAlpha=Math.min(1,e.t*2);ctx.fillStyle=e.type==='heal'?'#c3f7a1':'#ffe6b0';ctx.font='bold 12px monospace';ctx.textAlign='center';ctx.shadowColor='#000';ctx.shadowBlur=5;ctx.fillText(e.text,p.x,p.y);ctx.shadowBlur=0;ctx.globalAlpha=1}}}
function draw(ts){let dt=Math.min(.05,(ts-last)/1000||.016);last=ts;clock+=dt;ctx.setTransform(DPR,0,0,DPR,0,0);background();if(battle)battlefield(clock);else hangar(clock);effects.forEach(e=>e.t-=dt*(e.type==='shot'?3:1));effects=effects.filter(e=>e.t>0);requestAnimationFrame(draw)}
function screenTile(clientX,clientY){let sx=(clientX-origin.x)/(scale*.866),sy=(clientY-origin.y)/(scale*.42);return{x:Math.round((sx+sy)/2),z:Math.round((sy-sx)/2)}}
function pick(clientX,clientY){let best=null,dist=Infinity;for(let u of battle.units.filter(u=>u.alive)){let p=project(u.vx,1.4,u.vz),d=Math.hypot(clientX-p.x,(clientY-p.y)*.75);if(d<scale*.8&&d<dist){dist=d;best=u}}return best}
canvas.addEventListener('pointermove',e=>{if(!battle)return;let picked=pick(e.clientX,e.clientY),p=picked?{x:picked.x,z:picked.z}:screenTile(e.clientX,e.clientY);let changed=!hover||hover.x!==p.x||hover.z!==p.z;hover=p;if(changed&&picked?.team==='enemy')renderBattle()});
canvas.addEventListener('pointerdown',async e=>{if(!battle||battle.busy||!$('#modal').hidden)return;let picked=pick(e.clientX,e.clientY),p=picked?{x:picked.x,z:picked.z}:screenTile(e.clientX,e.clientY),u=current();hover=p;if(picked?.team==='ally'){selected=picked.index;renderBattle();return}if(!u)return;if(action==='move'){if(picked?.team==='enemy'){action='fire';renderBattle();toast('Target acquired. Select a subsystem, then tap again to fire.');return}let cost=paths(u).get(p.x+','+p.z);if(!cost)return toast('Choose a highlighted tile within movement range');battle.busy=true;await moveUnit(u,p.x,p.z,cost);battle.busy=false;renderBattle()}else{if(!picked||picked.team!=='enemy')return toast('Select a hostile mech');let w=weapon(u.weapon);if(u.hp.right<=0)return toast('Weapon arm destroyed. Move or brace to support your lance.');if(u.ap<w.ap)return toast('Not enough AP. Select another unit or end your turn.');if(distance(u,picked)>w.range)return toast('Target out of range. Move closer.');if(picked.hp[targetPart]<=0)return toast('Subsystem already destroyed. Select another target part.');battle.busy=true;renderBattle();await shoot(u,picked,targetPart);if(checkEnd())return;battle.busy=false;renderBattle()}});
document.addEventListener('keydown',e=>{if(!battle||battle.busy||!$('#modal').hidden||e.repeat)return;let key=e.key.toLowerCase();if(['m','f','q','e','1','2','3'].includes(key))e.preventDefault();if(key==='m'){action='move';renderBattle()}if(key==='f'){action='fire';renderBattle()}if(key==='q')skill();if(key==='e')endTurn();if(['1','2','3'].includes(key)){let i=+key-1;if(battle.units.find(u=>u.team==='ally'&&u.index===i&&u.alive)){selected=i;renderBattle()}}});
document.addEventListener('keydown',e=>{if(e.key==='Tab'&&!$('#modal').hidden){let btns=[...$('#modal').querySelectorAll('button')],first=btns[0],last=btns.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
render();requestAnimationFrame(draw);
